<?php
$root=getenv('WP_ROOT');if(!$root || !is_file($root.'/wp-load.php')){exit("Set WP_ROOT.\n");}$_SERVER['HTTP_HOST']='snd.test';$_SERVER['REQUEST_METHOD']='GET';$_SERVER['REQUEST_URI']='/';require $root.'/wp-load.php';
if(!in_array(wp_get_environment_type(),array('local','development'),true)){exit("Refusing production.\n");}
require __DIR__.'/legacy-mode.php';
$count=0;$saved_data=get_option('snd_dataset',null);$saved_overrides=get_option('snd_overrides',null);$saved_user=get_current_user_id();$users=array();$tokens=array();$day_key='snd_day_v3_'.str_replace('-','',SND_Game::date()).'_municipality';$saved_day=get_option($day_key,null);
function bg_ok($v,$label){global $count;$count++;if(!$v){throw new RuntimeException($label);}}
function bg_call($route,$body){$r=new WP_REST_Request('POST','/srbija-na-dlanu/v1/'.$route);$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($body));return rest_do_request($r);}
try{
    delete_option('snd_dataset');delete_option('snd_overrides');SND_Data::reset_cache();wp_set_current_user(0);$all=SND_Data::get()['territories'];$pool=SND_Data::pool('municipality');$boroughs=array_filter($pool,function($t){return ($t['parent_id']??'')==='m-beograd';});
    bg_ok(count($pool)===190 && count($boroughs)===17 && !isset($pool['m-beograd']),'190 playable units include 17 boroughs, no duplicate city');bg_ok(isset($all['m-beograd']) && SND_Data::retired_ids()===array('m-beograd'),'Legacy city identity retained');
    $expected=array('barajevo'=>26431,'vozdovac'=>174864,'vracar'=>55406,'grocka'=>82810,'zvezdara'=>172625,'zemun'=>177908,'lazarevac'=>55146,'mladenovac'=>48683,'novi-beograd'=>209763,'obrenovac'=>68882,'palilula'=>182624,'rakovica'=>104456,'savski-venac'=>36699,'sopot'=>19126,'stari-grad'=>44737,'surcin'=>45452,'cukarica'=>175793);$shapes=array();
    foreach($expected as $id=>$pop){$t=$boroughs['m-bg-'.$id];bg_ok($t['population']===$pop && $t['year']===2022,'RZS 2022 population '.$id);bg_ok($t['district_id']==='rs-00' && $t['boundary_source']==='https://kro.mre.gov.rs/arcgis/rest/services/IMIS/MINING_PUBLIC/MapServer/4','True parent and boundary source '.$id);bg_ok($t['center'][0]>44 && $t['center'][0]<46 && $t['center'][1]>19 && $t['center'][1]<22,'Belgrade geometric center '.$id);bg_ok(strlen($t['path'])>100 && strlen($t['map_path'])>100,'Both outlines '.$id);$shapes[]=$t['path'];
        foreach(array('sr','en','de','ru') as $lang){SND_I18n::force($lang);$q=SND_Game::questions($t,$pool,SND_Data::pool('district'),'bg:'.$id);$localized=SND_I18n::question($q[1],$t);bg_ok(count($q)===4 && $q[1]['type']==='city_membership','Borough has four complete rounds '.$id);bg_ok(array_column($q[1]['options'],'id')===array_column($localized['options'],'id') && $localized['correct']===$q[1]['correct'],'Stable localized answer IDs '.$id);bg_ok($lang==='sr' || $localized['title']!==$q[1]['title'],'Localized city question '.$id);$sources=SND_Game::geometry_sources(array($t));bg_ok(count($sources)===1 && strpos($sources[0]['url'],'mre.gov.rs')!==false,'Actual borough geometry attribution');}
    }
    bg_ok(count(array_unique($shapes))===17,'Seventeen distinct real outlines');bg_ok(array_sum(array_column($boroughs,'population'))===1681405,'Boroughs sum to whole Belgrade');bg_ok(array_sum(array_column($pool,'population'))===6647003,'National population remains unduplicated');bg_ok(count(array_filter($pool,function($t){return $t['region']==='Kosovo i Metohija';}))===29,'KiM stays included');
    $valid=SND_Data::validate(SND_Data::editable());bg_ok(!is_wp_error($valid),'Extended dataset validates');$rows=array_column($valid['territories'],null,'id');bg_ok($rows['m-bg-vracar']['parent_id']==='m-beograd' && $rows['m-bg-vracar']['boundary_source']===$boroughs['m-bg-vracar']['boundary_source'],'Parent and provenance survive export/import validation');
    $seed=require SND_DIR.'data/territories.php';$seed['territories'][0]['name']='Prilagođeno ime';update_option('snd_dataset',$seed,false);SND_Data::reset_cache();bg_ok(count(SND_Data::pool('municipality'))===190 && SND_Data::get()['territories']['rs-00']['name']==='Prilagođeno ime','Older/custom dataset gains boroughs without overwriting edits');delete_option('snd_dataset');SND_Data::reset_cache();
    $overrides=array();foreach($boroughs as $id=>$t){$overrides[$id]=array('disabled'=>true);}update_option('snd_overrides',$overrides,false);SND_Data::reset_cache();bg_ok(count(SND_Data::pool('municipality'))===174 && isset(SND_Data::pool('municipality')['m-beograd']) && !SND_Data::retired_ids(),'Disabling all boroughs restores whole-city fallback');delete_option('snd_overrides');SND_Data::reset_cache();
    $user=wp_insert_user(array('user_login'=>'snd-bg-'.bin2hex(random_bytes(6)),'user_pass'=>bin2hex(random_bytes(20)),'role'=>'subscriber'));$users[]=$user;$p=SND_Progress::get($user);$p['municipality']['discovered']=array('m-beograd','m-bg-vracar');$p['municipality']['practice_count']=7;update_user_meta($user,'snd_progress_v2',$p);$summary=SND_Progress::summary($user);bg_ok($summary['municipality']['discovered']===array('m-bg-vracar') && $summary['municipality']['practice_count']===7,'Current discovery count excludes the retired aggregate, totals stay intact');bg_ok(SND_Progress::get($user)['municipality']['discovered']===array('m-beograd','m-bg-vracar'),'Stored legacy discovery history is untouched');
    // A frozen pre-update daily challenge and an active legacy city remain valid.
    $old_pool=array();foreach($seed['territories'] as $t){if($t['kind']==='municipality'){$old_pool[$t['id']]=$t;}}$legacy=SND_Game::challenge('municipality','practice');$legacy['catalog']=$old_pool;$legacy['target']=$old_pool['m-beograd'];$legacy['questions']=SND_Game::questions($legacy['target'],$old_pool,SND_Data::pool('district'),'bg:legacy');$legacy['mode']='daily';$legacy['ruleset']=3;$legacy['storage_key']=$day_key;update_option($day_key,$legacy,false);$current_day=SND_Game::challenge('municipality','daily');bg_ok(get_option($day_key)===$legacy && $current_day['ruleset']===SND_Game::RULESET,'New daily season retains the old frozen challenge unchanged');
    $s=array('challenge'=>$legacy,'stage'=>'guess','guesses'=>array(),'hint'=>false,'solved'=>false,'answers'=>array(),'question_index'=>0,'revision'=>0,'owner'=>0,'game_id'=>bin2hex(random_bytes(16)),'recorded'=>false);$token=bin2hex(random_bytes(24));$tokens[]=$token;SND_Game::persist($token,$s);$r=bg_call('action',array('token'=>$token,'revision'=>0,'action'=>'guess','value'=>'m-beograd'));bg_ok($r->get_status()===200 && $r->get_data()['state']['solved'],'Legacy whole-city answer still accepted');
    SND_I18n::force('sr');echo 'PASS: '.$count.' Belgrade geometry, census, quiz, provenance, migration and progress assertions.'.PHP_EOL;
}finally{
    require_once ABSPATH.'wp-admin/includes/user.php';foreach($users as $u){wp_delete_user($u);}foreach($tokens as $token){delete_transient('snd_session_'.$token);}foreach(array('snd_dataset'=>$saved_data,'snd_overrides'=>$saved_overrides,$day_key=>$saved_day) as $key=>$value){if($value===null){delete_option($key);}else{update_option($key,$value,false);}}SND_Data::reset_cache();SND_I18n::force(null);wp_set_current_user($saved_user);
}
